module Tests
open Solution

let ordered xs =
    xs |> List.pairwise |> List.forall (fun (a, b) -> a <= b)

let count value xs =
    xs |> List.filter (fun item -> item = value) |> List.length

let preserves xs ys =
    let sameLength = List.length xs = List.length ys
    let sameCounts = List.forall (fun value -> count value xs = count value ys) xs
    sameLength && sameCounts

// Each pair names an observation made by running the implementation.
let examples () : (string * bool) array =
    [| "empty input stays empty" , sort [] = []
       "duplicate requests stay present" , sort [3; 1; 1] = [1; 1; 3] |]

let property (xs: int list) : bool =
    ordered (sort xs) && preserves xs (sort xs)

typescript.Tests.ts:
import { sort } from "./Solution.ts";
export const examples = () => [
  ["empty input stays empty", sort([]).length === 0],
  ["duplicate requests stay present", JSON.stringify(sort([3,1,1])) === "[1,1,3]"]
];

export const property = (xs: number[]) => (() => { const out = sort(xs); return out.every((x, i) => i === 0 || out[i-1] <= x) && out.length === xs.length && xs.every(x => out.filter(y => y === x).length === xs.filter(y => y === x).length); })();

